import sys

def main():
    data = sys.stdin.read().splitlines()
    s1 = data[0] if len(data) > 0 else ''
    s2 = data[1] if len(data) > 1 else ''

    set2 = set(s2)
    seen = set()
    res = []

    for ch in s1:
        if ch in set2 and ch not in seen:
            seen.add(ch)
            res.append(ch)

    if not res:
        print(-1)
    else:
        print(''.join(res))

if __name__ == "__main__":
    main()
